import re
from typing import Any


def od_rows(type_slug: str, q: str = "") -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    cursor: str | None = None
    for _ in range(100):
        if q:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor, q=q)
        else:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor)
        out.extend(page.get("records") or [])
        cursor = page.get("nextCursor")
        if not cursor:
            break
    return out


def od_data(row: Any) -> dict[str, Any]:
    return dict((row or {}).get("data") or {})


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


def od_norm(value: Any) -> str:
    return re.sub(r"[^a-z0-9]+", " ", od_text(value).lower()).strip()


def od_link_ids(row: Any, field: str) -> list[str]:
    out: list[str] = []
    for ref in ((row or {}).get("links") or {}).get(field) or []:
        if isinstance(ref, dict) and ref.get("id"):
            out.append(str(ref["id"]))
        elif isinstance(ref, str):
            out.append(ref)
    return out


def od_order_lines(order_id: str, order_number: str) -> list[dict[str, Any]]:
    found = [r for r in od_rows("od_order_lines", order_number) if order_id in od_link_ids(r, "order")]
    if not found:
        found = [r for r in od_rows("od_order_lines") if order_id in od_link_ids(r, "order")]
    found.sort(key=lambda r: float(od_data(r).get("line_number") or 0))
    return found


import difflib
import math

UNIT_WORDS = {
    "carton": ["carton", "cartons", "ctn", "ctns", "box", "boxes", "bx", "case", "cases", "cs"],
    "tray": ["tray", "trays", "flat", "flats"],
    "bag": ["bag", "bags", "sack", "sacks"],
    "crate": ["crate", "crates"],
    "each": ["each", "ea", "pc", "pcs", "piece", "pieces", "unit", "units"],
    "kg": ["kg", "kgs", "kilo", "kilos", "kilogram", "kilograms"],
    "bunch": ["bunch", "bunches", "bch", "bn"],
    "punnet": ["punnet", "punnets", "pun", "pnt"],
}
UNIT_CLASS: dict[str, str] = {}
for unit_class, words in UNIT_WORDS.items():
    for word in words:
        UNIT_CLASS[word] = unit_class
UNIT_CLASS["box"] = "carton"


def unit_class_of(value: Any) -> str:
    word = re.sub(r"[^a-z]", "", od_text(value).lower())
    return UNIT_CLASS.get(word, word)


def as_number(value: Any) -> float:
    try:
        return float(re.sub(r"[^0-9.\-]", "", str(value)) or 0)
    except ValueError:
        return 0.0


def tidy(value: float) -> float:
    return round(value, 3)


order_id = params["order_id"]
order_number = od_text(params.get("order_number"))
account_code = od_text(params.get("account_code"))
read_lines: list[dict[str, Any]] = [dict(x) for x in (params.get("lines") or []) if isinstance(x, dict)]
products = [r for r in od_rows("od_products") if od_data(r).get("active") is not False]
by_code: dict[str, dict[str, Any]] = {od_text(od_data(r).get("item_code")).upper(): r for r in products}
by_name: dict[str, dict[str, Any]] = {od_norm(r.get("title")): r for r in products}
catalogue = [r for r in od_rows("od_customer_catalogue", account_code) if od_text(od_data(r).get("account_code")) == account_code] if account_code else []
existing: dict[int, dict[str, Any]] = {}
for row in od_order_lines(order_id, order_number):
    existing[int(float(od_data(row).get("line_number") or 0))] = row
lines: list[dict[str, Any]] = []
flags: list[str] = []
number = 0
for read in read_lines[:200]:
    number += 1
    line_number = int(as_number(read.get("line_number")) or number)
    raw_text = od_text(read.get("raw_text"))
    customer_code = od_text(read.get("customer_code"))
    description = od_text(read.get("description")) or raw_text
    raw_unit = od_text(read.get("unit"))
    has_quantity = od_text(read.get("quantity")) != ""
    raw_quantity = as_number(read.get("quantity"))
    product: dict[str, Any] = {}
    mapping: dict[str, Any] = {}
    match_result = "unmatched"
    note = ""
    if customer_code:
        rows = [r for r in catalogue if od_text(od_data(r).get("customer_code")).upper() == customer_code.upper()]
        if rows:
            same_unit = [r for r in rows if unit_class_of(od_data(r).get("customer_unit")) == unit_class_of(raw_unit)]
            mapping = (same_unit or rows)[0]
            product = by_code.get(od_text(od_data(mapping).get("item_code")).upper(), {})
            if product:
                match_result = "matched"
                note = "Customer code " + customer_code + " is in their catalogue."
        if not product and customer_code.upper() in by_code:
            product = by_code[customer_code.upper()]
            match_result = "matched"
            note = "The code is one of our item codes."
    if not product and description:
        wanted = od_norm(description)
        if wanted in by_name:
            product = by_name[wanted]
            match_result = "matched"
        else:
            described = [r for r in catalogue if od_norm(od_data(r).get("customer_description")) == wanted]
            items = {od_text(od_data(r).get("item_code")).upper() for r in described}
            if len(items) == 1 and list(items)[0] in by_code:
                product = by_code[list(items)[0]]
                match_result = "matched"
                note = "Matched on the customer's own description."
        if not product:
            words = set(wanted.split())
            inside = [r for name, r in by_name.items() if words and (set(name.split()) <= words or words <= set(name.split()))]
            if len(inside) == 1:
                product = inside[0]
                match_result = "guessed"
                note = "Closest product by name; please check."
            else:
                close = difflib.get_close_matches(wanted, list(by_name.keys()), n=2, cutoff=0.84)
                if len(close) == 1:
                    product = by_name[close[0]]
                    match_result = "guessed"
                    note = "Closest product by name; please check."
    quantity = raw_quantity
    unit = raw_unit
    needs_review = match_result != "matched"
    item_code = ""
    product_name = ""
    if product:
        p = od_data(product)
        item_code = od_text(p.get("item_code"))
        product_name = od_text(product.get("title"))
        sell_unit = od_text(p.get("sell_unit"))
        base_unit = od_text(p.get("base_unit"))
        pack = as_number(p.get("units_per_pack"))
        unit = sell_unit
        given = unit_class_of(raw_unit)
        if not mapping:
            fits = [r for r in catalogue if od_text(od_data(r).get("item_code")).upper() == item_code.upper() and raw_unit and unit_class_of(od_data(r).get("customer_unit")) == given]
            mapping = fits[0] if fits else {}
        factor = as_number(od_data(mapping).get("conversion_factor")) if mapping else 0.0
        mapping_unit = unit_class_of(od_data(mapping).get("customer_unit")) if mapping else ""
        rounding = od_text(od_data(mapping).get("rounding")) if mapping and mapping_unit == given else ""
        exact = raw_quantity
        converted = False
        if not has_quantity or raw_quantity <= 0:
            needs_review = True
            note = (note + " No quantity could be read.").strip()
        elif not raw_unit:
            needs_review = True
            flags.append("unit_missing")
            note = (note + " No unit was written, so the selling unit (" + sell_unit + ") was assumed.").strip()
        elif mapping and factor > 0 and factor != 1 and (mapping_unit == given or not mapping_unit):
            exact = raw_quantity * factor
            converted = True
        elif given == unit_class_of(sell_unit):
            exact = raw_quantity
        elif given == unit_class_of(base_unit) and pack > 0:
            exact = raw_quantity / pack
            converted = True
        elif mapping and factor == 1 and mapping_unit == given:
            exact = raw_quantity
        else:
            needs_review = True
            flags.append("unit_mismatch")
            note = (note + " The unit '" + raw_unit + "' could not be converted to " + sell_unit + ".").strip()
        if converted:
            if match_result == "matched":
                match_result = "converted"
            exact = tidy(exact)
            whole = abs(exact - round(exact)) < 0.0005
            note = (note + " " + od_text(raw_quantity).rstrip("0").rstrip(".") + " " + raw_unit + " = " + od_text(exact) + " " + sell_unit + (" (pack of " + od_text(pack).rstrip("0").rstrip(".") + " " + base_unit + ")" if pack > 0 else "") + ".").strip()
            if whole:
                exact = float(round(exact))
            else:
                needs_review = True
                flags.append("unit_mismatch")
            if whole:
                pass
            elif rounding == "up":
                exact = float(math.ceil(exact))
                note += " Rounded up to full selling units."
            elif rounding == "down":
                exact = float(math.floor(exact))
                note += " Rounded down to full selling units."
            elif rounding == "nearest":
                exact = float(round(exact))
                note += " Rounded to the nearest selling unit."
            else:
                note += " This is not a whole number of selling units."
        quantity = tidy(exact)
    else:
        flags.append("unknown_product")
        note = "No product matches this line."
    confidence = od_text(read.get("confidence")).lower()
    if confidence not in ("high", "medium", "low"):
        confidence = "medium"
    if confidence == "low":
        needs_review = True
    data: dict[str, Any] = {
        "line_number": line_number,
        "raw_text": raw_text[:500],
        "customer_code": customer_code[:120],
        "raw_unit": raw_unit[:40],
        "line_note": od_text(read.get("note"))[:500],
        "item_code": item_code,
        "quantity": quantity,
        "unit": unit[:40],
        "conversion_note": note[:500],
        "match_result": match_result,
        "read_confidence": confidence,
        "needs_review": needs_review,
    }
    if has_quantity:
        data["raw_quantity"] = tidy(raw_quantity)
    links: dict[str, Any] = {"order": [order_id]}
    if product:
        links["product"] = [product["id"]]
    record: dict[str, Any] = {"title": (order_number + " / " + str(line_number)), "data": data, "links": links}
    if line_number in existing:
        saved = api.records.update(type_slug="od_order_lines", record_id=existing[line_number]["id"], record=record)
    else:
        saved = api.records.create(type_slug="od_order_lines", record=record)
    lines.append({
        "line_number": line_number,
        "line_id": od_text(saved.get("id")) or od_text(existing.get(line_number, {}).get("id")),
        "raw_text": raw_text,
        "item_code": item_code,
        "product_name": product_name,
        "quantity": quantity,
        "unit": unit,
        "match_result": match_result,
        "needs_review": needs_review,
        "note": note,
    })
flags = sorted(set(flags))
line_count = len(lines)
review_count = len([x for x in lines if x["needs_review"]])
